#!/usr/bin/env bash
# Day-5 bundle: GPQA option-shuffle fix + AIME25 benchmark + validation queue.
set -e
if [ ! -d "src/tokenguard" ]; then echo "ERROR: run from TokenGuard repo root"; exit 1; fi
decode() { base64 -d > "$1"; echo "  wrote $1"; }
echo "Installing Day-5 bundle..."
decode "apply_gpqa_shuffle.py" << 'B64EOF'

B64EOF
decode "apply_aime25.py" << 'B64EOF'

B64EOF
decode "apply_aime25_wiring.py" << 'B64EOF'

B64EOF
decode "run_queue_day5.sh" << 'B64EOF'

B64EOF
python apply_gpqa_shuffle.py && rm apply_gpqa_shuffle.py
python apply_aime25.py && rm apply_aime25.py
python apply_aime25_wiring.py && rm apply_aime25_wiring.py
chmod +x run_queue_day5.sh
echo ""
echo "Installed. Verify loaders, then queue:"
echo "  python -c \"import sys; sys.path.insert(0,'src'); from tokenguard.reasoning.datasets import load_benchmark; d=load_benchmark('aime25',limit=2); print(d[0]['id'], repr(d[0]['answer'])); g=load_benchmark('gpqa_diamond',limit=5); print('gpqa answers:', [x['answer'] for x in g])\""
echo "  bash run_queue_day5.sh --dry && bash run_queue_day5.sh"